UPDATE "BOARD" SET BOARD_VIEW_COUNT =
BOARD_VIEW_COUNT + 1
WHERE BOARD_NO = #{boardNo}

mapper.select:
SELECT COUNT(*) FROM "BOARD"
WHERE MEMBER_NO =
#{memberNo}
AND BOARD_CODE = #{boardCode}
AND BOARD_DEL_FL = 'N'

SELECT BOARD_NO, BOARD_TITLE, MEMBER_NICKNAME, BOARD_VIEW_COUNT, (SELECT COUNT(*) FROM "COMMENT" C WHERE C.BOARD_NO = B.BOARD_NO AND COMMENT_DEL_FL = 'N') COMMENT_COUNT, (SELECT COUNT(*) FROM "BOARD_LIKE" L WHERE L.BOARD_NO = B.BOARD_NO) LIKE_COUNT,
CASE WHEN SYSDATE - BOARD_WRITE_DATE < 1 / 24 / 60 THEN FLOOR((SYSDATE - B.BOARD_WRITE_DATE) * 24 * 60 * 60) || '초 전' WHEN SYSDATE - BOARD_WRITE_DATE < 1 / 24 THEN FLOOR((SYSDATE - B.BOARD_WRITE_DATE) * 24 * 60) || '분 전' WHEN SYSDATE - BOARD_WRITE_DATE < 1 THEN FLOOR((SYSDATE - B.BOARD_WRITE_DATE) * 24) || '시간 전' ELSE TO_CHAR(B.BOARD_WRITE_DATE, 'YYYY-MM-DD') END BOARD_WRITE_DATE FROM "BOARD" B JOIN "MEMBER" USING(MEMBER_NO) WHERE BOARD_DEL_FL = 'N'
AND CATEGORY_CODE = #{categoryCode}
AND BOARD_CODE = #{boardCode}
AND MEMBER_NO = #{memberNo} ORDER BY BOARD_NO DESC

SELECT * FROM ( SELECT BOARD_NO, BOARD_TITLE, BOARD_VIEW_COUNT, (SELECT COUNT(*) FROM "COMMENT" C WHERE C.BOARD_NO = B.BOARD_NO AND COMMENT_DEL_FL = 'N') AS COMMENT_COUNT, (SELECT COUNT(*) FROM "BOARD_LIKE" L WHERE L.BOARD_NO = B.BOARD_NO) LIKE_COUNT FROM "BOARD" B WHERE BOARD_DEL_FL = 'N'
AND CATEGORY_CODE = #{categoryCode}
AND BOARD_CODE = #{boardCode}
AND (SELECT COUNT(*) FROM "BOARD_LIKE" L WHERE L.BOARD_NO = B.BOARD_NO) > 0 ORDER BY LIKE_COUNT DESC, COMMENT_COUNT DESC, BOARD_VIEW_COUNT DESC ) WHERE ROWNUM <= 5
